/* Canadian Editorial industry news; data is generated by the repository workflow. */
(() => {
  "use strict";
  const root = document.getElementById("industry-news");
  if (!root) return;

  const nav = root.querySelector("[data-news-filters]");
  const cards = root.querySelector("[data-news-cards]");
  const status = root.querySelector("[data-news-status]");
  const updated = root.querySelector("[data-news-updated]");
  const count = root.querySelector("[data-news-count]");
  const more = root.querySelector("[data-news-more]");
  const categories = ["All", "Salesforce", "Microsoft", "AI", "Zoom", "Tech", "Business Analysis"];
  const fallback = {
    Salesforce: "https://developer.salesforce.com/blogs/",
    Microsoft: "https://techcommunity.microsoft.com/",
    AI: "https://openai.com/news/",
    Zoom: "https://www.zoom.com/en/blog/",
    Tech: "https://arstechnica.com/",
    "Business Analysis": "https://www.iiba.org/business-analysis-blogs/"
  };
  let articles = [], current = "All", expanded = false;

  const el = (tag, className, value) => {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (value !== undefined) node.textContent = value;
    return node;
  };
  const isSafe = link => {
    try {
      const u = new URL(link);
      return u.protocol === "https:";
    } catch (_) { return false; }
  };
  const formatDate = iso => {
    const d = new Date(iso);
    return Number.isNaN(d.getTime()) ? "" :
      new Intl.DateTimeFormat("en-CA", {month:"short", day:"numeric", year:"numeric", timeZone:"UTC"}).format(d);
  };
  function setStatus(message) {
    if (status) status.textContent = message;
  }
  function showFallback() {
    cards.replaceChildren();
    const wrapper = el("div", "news-empty");
    wrapper.append(el("p", "", "The live news feed is being prepared. Browse these trusted sources in the meantime:"));
    const links = el("div", "news-source-links");
    Object.entries(fallback).forEach(([category, url]) => {
      if (current !== "All" && current !== category) return;
      const a = el("a", "", category);
      a.href = url; a.target = "_blank"; a.rel = "noopener noreferrer";
      links.append(a);
    });
    wrapper.append(links);
    cards.append(wrapper);
    if (more) more.hidden = true;
  }
  function paint() {
    nav.querySelectorAll("button").forEach(button => {
      const active = button.dataset.topic === current;
      button.classList.toggle("is-active", active);
      button.setAttribute("aria-pressed", String(active));
    });
    const matching = articles.filter(item => current === "All" || item.category === current);
    if (count) count.textContent = matching.length ? String(matching.length) + " recent articles" : "";
    if (!matching.length) {
      showFallback();
      if (articles.length) setStatus("No recent articles in this category.");
      return;
    }
    cards.replaceChildren();
    for (const item of matching.slice(0, expanded ? 18 : 6)) {
      const article = el("article","news-card");
      const top = el("div","news-card-meta");
      top.append(el("span","news-category",item.category));
      top.append(el("span","news-date",formatDate(item.published_at)));
      const heading = el("h3","news-card-title");
      const anchor = el("a","",item.title);
      anchor.href = item.url; anchor.target = "_blank"; anchor.rel = "noopener noreferrer";
      heading.append(anchor);
      const excerpt = el("p","news-card-excerpt",item.summary || "Read the full update at the original source.");
      const bottom = el("div","news-card-bottom");
      bottom.append(el("span","news-source",item.source));
      const read = el("a","news-read","Read article ↗");
      read.href = item.url; read.target = "_blank"; read.rel = "noopener noreferrer";
      bottom.append(read);
      article.append(top,heading,excerpt,bottom);
      cards.append(article);
    }
    if (more) {
      more.hidden = matching.length <= 6;
      more.textContent = expanded ? "Show fewer stories" : "View more stories";
    }
  }
  nav.replaceChildren();
  categories.forEach(category => {
    const button = el("button","news-filter",category);
    button.type = "button"; button.dataset.topic = category;
    button.setAttribute("aria-pressed",String(category === current));
    button.addEventListener("click", () => {
      current = category; expanded = false; paint();
    });
    nav.append(button);
  });
  more?.addEventListener("click", () => { expanded = !expanded; paint(); });
  showFallback();
  setStatus("Checking the latest updates…");

  fetch("/Oba/previews/canadian/data/news.json?v=" + Math.floor(Date.now() / 300000), {cache:"no-store"})
    .then(response => {
      if (!response.ok) throw new Error("Feed not yet generated");
      return response.json();
    })
    .then(data => {
      articles = (Array.isArray(data.articles) ? data.articles : [])
        .filter(item => item && categories.includes(item.category) && item.category !== "All" &&
          typeof item.title === "string" && typeof item.url === "string" && isSafe(item.url) &&
          typeof item.published_at === "string")
        .sort((a,b) => new Date(b.published_at) - new Date(a.published_at));
      const date = data.updated_at ? new Date(data.updated_at) : null;
      if (updated && date && !Number.isNaN(date.getTime())) {
        updated.textContent = "Last refreshed " + new Intl.DateTimeFormat("en-CA", {
          month:"short",day:"numeric",year:"numeric",hour:"numeric",minute:"2-digit"
        }).format(date);
      }
      setStatus(articles.length ? "Stories from publisher feeds · Updated automatically" : "No articles have been collected yet.");
      paint();
    })
    .catch(() => {
      setStatus("Live headlines will appear after the first successful news refresh.");
      showFallback();
    });
})();
